220	  private buildTrendGrid(report: DailyReport): string {
221	    const trends = report.trend_analysis;
222	    const dims: Array<{ key: string; label: string }> = [
223	      { key: 'technology', label: '技术' },
224	      { key: 'application', label: '应用' },
225	      { key: 'policy', label: '政策' },
226	      { key: 'capital', label: '资本' },
227	    ];
228	
229	    return dims
230	      .map((dim) => {
231	        const td = (trends as any)[dim.key] as { trend: string; confidence: number; signals: string[] } | undefined;
232	        if (!td || !td.trend) {
233	          return `
234	    <div class="trend-card">
235	      <div class="dim">${dim.label}</div>
236	      <p>暂无趋势数据</p>
237	    </div>`;
238	        }
239	
240	        const signals = td.signals?.length > 0
241	          ? `<ul>${td.signals.map((s) => `<li>${this.escapeHtml(s)}</li>`).join('')}</ul>`
242	          : '';
243	
244	        const confPct = Math.round(td.confidence * 100);
245	
246	        return `
247	    <div class="trend-card">
248	      <div class="dim">${dim.label}</div>
249	      <span class="conf">可信度: ${confPct}%</span>
250	      <p>${this.escapeHtml(td.trend)}</p>
251	      ${signals}
252	    </div>`;
253	      })
254	      .join('');
255	  }
