257	  private buildRiskOpportunity(report: DailyReport): string {
258	    const ro = report.risk_opportunity;
259	    let html = '';
260	
261	    // Risks
262	    if (ro.risks && ro.risks.length > 0) {
263	      html += '<h3>风险</h3>';
264	      html += ro.risks
265	        .map((r) => {
266	          const levelClass = r.level === 'high' || r.level === 'critical' ? 'risk-high' : '';
267	          return `
268	    <div class="${levelClass}" style="border-left: 4px solid ${r.level === 'critical' ? '#DC2626' : r.level === 'high' ? '#F59E0B' : '#9CA3AF'}; padding: 8px 16px; margin: 8px 0; background: #FEF2F2; border-radius: 4px;">
269	      <strong>[${r.level.toUpperCase()}]</strong> ${this.escapeHtml(r.description)}
270	      <br><small>概率: ${r.probability} | 类型: ${r.type} | 建议: ${this.escapeHtml(r.suggested_action)}</small>
271	    </div>`;
272	        })
273	        .join('');
274	    } else {
275	      html += '<p>暂无风险数据</p>';
276	    }
277	
278	    // Opportunities
279	    if (ro.opportunities && ro.opportunities.length > 0) {
280	      html += '<h3>机会</h3>';
281	      html += ro.opportunities
282	        .map((o) => {
283	          return `
284	    <div class="opportunity">
285	      <strong>${this.escapeHtml(o.description)}</strong>
286	      <br><small>类别: ${o.category} | 时间窗口: ${o.time_window} | 依据: ${this.escapeHtml(o.rationale)}</small>
287	    </div>`;
288	        })
289	        .join('');
290	    } else {
291	      html += '<p>暂无机会数据</p>';
292	    }
293	
294	    return html;
295	  }
