297	  private buildAppendix(report: DailyReport): string {
298	    const refs = report.references_index;
299	    if (!refs || refs.length === 0) {
300	      return '<p>暂无引用数据</p>';
301	    }
302	
303	    const rows = refs
304	      .map((ref) => {
305	        return `
306	    <tr>
307	      <td>${this.escapeHtml(ref.id)}</td>
308	      <td>${this.escapeHtml(ref.title)}</td>
309	      <td>${this.escapeHtml(ref.source_name)}</td>
310	      <td><a href="${this.escapeHtml(ref.source_url)}" target="_blank" rel="noopener">${this.escapeHtml(ref.source_url)}</a></td>
311	    </tr>`;
312	      })
313	      .join('');
314	
315	    return `
316	    <table>
317	      <thead>
318	        <tr><th>ID</th><th>标题</th><th>来源</th><th>链接</th></tr>
319	      </thead>
320	      <tbody>
321	        ${rows}
322	      </tbody>
323	    </table>`;
324	  }
